/* IaC Generator + Cloud Configurator */
(function () {
  const { h, raw, ui, data: D } = COC, { STAFF } = COC.roleSets;

  /* ================= IaC GENERATOR ================= */
  const IS = { tpl: 'k8s', cloud: 'AWS', region: 'eu-west-1', name: 'coc-demo', nodes: 3, size: 'm5.large', cidr: '10.40.0.0/16', cc: 'CC-421', pub: false, enc: true, tab: 'tf', planned: null, out: null, pushed: null };
  const SIZES = { AWS: ['t3.medium', 'm5.large', 'm5.2xlarge'], Azure: ['Standard_D2s_v5', 'Standard_D4s_v5'], GCP: ['e2-standard-2', 'n2-standard-4'], OpenShift: ['m5.xlarge'], 'IBM Cloud': ['bx2-4x16', 'bx2-8x32'] };
  const TPL = { k8s: 'Managed Kubernetes cluster (Golden Path)', vm: 'Virtual machine group', net: 'VPC / VNet network baseline', ocp: 'OpenShift namespace + quota' };
  COC.actions['iac.set'] = (v, el) => { const k = el.dataset.arg; IS[k] = el.type === 'checkbox' ? el.checked : (k === 'nodes' ? +v : v); if (k === 'cloud') { IS.region = D.cloudMeta[v].regions[0]; IS.size = SIZES[v][0]; } IS.out = null; IS.planned = null; COC.refresh(); };
  COC.actions['iac.tab'] = t => { IS.tab = t; COC.refresh(); };
  function policyCheck() {
    const R = [];
    const rule = (id, ok, msg) => R.push({ id, ok, msg, mode: D.policies.find(p => p.id === id).mode });
    rule('require-tags', !!IS.cc.trim(), IS.cc.trim() ? 'tags env/team/cost_center present' : 'cost_center tag missing');
    rule('no-public-s3', !IS.pub, IS.pub ? 'public endpoint / bucket requested' : 'no public exposure');
    rule('encrypt-at-rest', IS.enc, IS.enc ? 'encryption enabled' : 'encryption disabled');
    rule('approved-regions', true, 'region approved');
    return R;
  }
  function terraform() {
    const n = IS.name, tags = `{ env = "dev", team = "platform", cost_center = "${IS.cc}" }`;
    if (IS.tpl === 'net') return `# network baseline – ${IS.cloud}\nresource "${IS.cloud === 'AWS' ? 'aws_vpc' : IS.cloud === 'Azure' ? 'azurerm_virtual_network' : 'google_compute_network'}" "${n}" {\n  ${IS.cloud === 'AWS' ? `cidr_block = "${IS.cidr}"` : `address_space = ["${IS.cidr}"]`}\n  tags = ${tags}\n}\n`;
    if (IS.tpl === 'ocp') return `provider "kubernetes" { config_path = "~/.kube/config" }\n\nresource "kubernetes_namespace" "${n}" {\n  metadata { name = "${n}"\n    labels = { cost_center = "${IS.cc}" } }\n}\n\nresource "kubernetes_resource_quota" "${n}" {\n  metadata { name = "default-quota"\n    namespace = kubernetes_namespace.${n}.metadata[0].name }\n  spec { hard = { "requests.cpu" = "${IS.nodes * 4}", "requests.memory" = "${IS.nodes * 16}Gi" } }\n}\n`;
    if (IS.tpl === 'vm') return `resource "${IS.cloud === 'AWS' ? 'aws_instance' : IS.cloud === 'Azure' ? 'azurerm_linux_virtual_machine' : 'google_compute_instance'}" "${n}" {\n  count         = ${IS.nodes}\n  ${IS.cloud === 'AWS' ? 'instance_type' : 'size'} = "${IS.size}"\n  ${IS.cloud === 'AWS' ? `associate_public_ip_address = ${IS.pub}` : ''}\n  tags          = ${tags}\n}\n`;
    const body = {
      AWS: `module "vpc" {\n  source = "terraform-aws-modules/vpc/aws"\n  name   = "${n}-vpc"\n  cidr   = "${IS.cidr}"\n}\n\nmodule "eks" {\n  source          = "terraform-aws-modules/eks/aws"\n  cluster_name    = "${n}"\n  cluster_endpoint_public_access = ${IS.pub}\n  vpc_id          = module.vpc.vpc_id\n  eks_managed_node_groups = {\n    default = { desired_size = ${IS.nodes}, instance_types = ["${IS.size}"] }\n  }\n  tags = ${tags}\n}`,
      Azure: `resource "azurerm_kubernetes_cluster" "${n}" {\n  name                = "${n}"\n  location            = "${IS.region}"\n  dns_prefix          = "${n}"\n  private_cluster_enabled = ${!IS.pub}\n  default_node_pool { name = "default"\n    node_count = ${IS.nodes}\n    vm_size    = "${IS.size}" }\n  tags = ${tags}\n}`,
      GCP: `resource "google_container_cluster" "${n}" {\n  name     = "${n}"\n  location = "${IS.region}"\n  initial_node_count = ${IS.nodes}\n  private_cluster_config { enable_private_nodes = ${!IS.pub} }\n  node_config { machine_type = "${IS.size}" }\n  resource_labels = ${tags}\n}`,
      OpenShift: `resource "rhcs_cluster_rosa_classic" "${n}" {\n  name           = "${n}"\n  cloud_region   = "${IS.region}"\n  compute_machine_type = "${IS.size}"\n  replicas       = ${IS.nodes}\n  tags           = ${tags}\n}`,
      'IBM Cloud': `resource "ibm_container_vpc_cluster" "${n}" {\n  name         = "${n}"\n  flavor       = "${IS.size}"\n  worker_count = ${IS.nodes}\n}`,
    };
    return `terraform {\n  required_version = ">= 1.6"\n}\n\n# Generated by CloudOps Console – ${IS.cloud} / ${IS.region}\n${body[IS.cloud]}\n\noutput "cluster_name" { value = "${n}" }\n`;
  }
  function ansible() {
    return `---\n- name: Post-provision hardening for ${IS.name}\n  hosts: ${IS.name}\n  become: true\n  tasks:\n    - name: Ensure chrony is installed\n      ansible.builtin.package: { name: chrony, state: present }\n    - name: Apply CIS sysctl baseline\n      ansible.posix.sysctl: { name: net.ipv4.ip_forward, value: "0", state: present }\n    - name: Register with CoC agent\n      ansible.builtin.shell: coc-agent register --tenant "${COC.state.tenant}" --cc ${IS.cc}\n      no_log: true\n`;
  }
  COC.actions['iac.gen'] = () => {
    const pol = policyCheck(), blocked = pol.filter(p => !p.ok && p.mode === 'enforce');
    if (blocked.length) { COC.audit('IaC generation BLOCKED by policy', blocked.map(b => b.id).join(',')); COC.toast('Blocked by policy: ' + blocked.map(b => b.id).join(', '), 'bad'); IS.out = null; COC.refresh(); return; }
    IS.out = { tf: terraform(), an: ansible() }; IS.planned = null; COC.audit('IaC generated', IS.name + ' (' + IS.cloud + ')'); COC.toast('Terraform + Ansible generated', 'ok'); COC.refresh();
  };
  COC.actions['iac.plan'] = () => { if (!IS.out) return COC.toast('Generate first', 'warn'); IS.planned = 'running'; COC.refresh(); setTimeout(() => { const add = IS.tpl === 'k8s' ? 14 + IS.nodes : IS.tpl === 'net' ? 9 : 3 + IS.nodes; IS.planned = { add, change: 0, destroy: 0, cost: IS.nodes * (IS.tpl === 'vm' ? 70 : 95) + (IS.tpl === 'k8s' ? 73 : 0) }; COC.audit('IaC plan (dry-run)', IS.name); COC.refresh(); }, 900); };
  COC.actions['iac.push'] = () => { if (!IS.out) return COC.toast('Generate first', 'warn'); IS.pushed = 'git@github.com:acme/infra.git → branch coc/' + IS.name; COC.audit('IaC pushed to git', IS.pushed); COC.toast('Pushed to ' + IS.pushed, 'ok'); COC.refresh(); };
  COC.actions['iac.dl'] = () => { if (!IS.out) return COC.toast('Generate first', 'warn'); COC.download(IS.name + '.tf', IS.out.tf); COC.download(IS.name + '-playbook.yml', IS.out.an); };
  COC.register({ id: 'iac', name: 'IaC Generator', icon: '🏗️', phase: 3, roles: STAFF, render() {
    const pol = policyCheck(), fld = (k, l, t) => h`<label class="f">${l}<input data-chg="iac.set" data-arg="${k}" value="${IS[k]}" ${t ? raw('type="' + t + '"') : ''}></label>`;
    return h`<div class="ph"><div class="grow"><h1>IaC Generator</h1><p class="sub">GUI form → Terraform HCL + Ansible playbook. Policy-as-code gate runs <i>before</i> code is generated.</p></div></div>
      <div class="grid g12"><div class="card"><h2>1 · Describe what you want</h2>
        <label class="f">Golden-path template<select data-chg="iac.set" data-arg="tpl">${Object.entries(TPL).map(([k, v]) => h`<option value="${k}" ${k === IS.tpl ? raw('selected') : ''}>${v}</option>`)}</select></label>
        <label class="f">Cloud${ui.select('iac-cloud', D.clouds, IS.cloud, 'iac.set', 'cloud')}</label><label class="f">Region${ui.select('iac-region', D.cloudMeta[IS.cloud].regions, IS.region, 'iac.set', 'region')}</label>
        ${fld('name', 'Name')}${fld('nodes', 'Node / instance count', 'number')}<label class="f">Size${ui.select('iac-size', SIZES[IS.cloud], IS.size, 'iac.set', 'size')}</label>${fld('cidr', 'Network CIDR')}${fld('cc', 'cost_center tag (required by policy)')}
        <label class="row" style="margin-bottom:8px"><input type="checkbox" data-chg="iac.set" data-arg="pub" ${IS.pub ? raw('checked') : ''}> Expose publicly</label><label class="row"><input type="checkbox" data-chg="iac.set" data-arg="enc" ${IS.enc ? raw('checked') : ''}> Encrypt at rest</label></div>
      <div><div class="card"><h2>2 · Policy gate (OPA)</h2>${pol.map(p => h`<div class="row" style="margin-bottom:4px">${p.ok ? ui.badge('PASS', 'ok') : ui.badge(p.mode === 'enforce' ? 'BLOCK' : 'WARN', p.mode === 'enforce' ? 'bad' : 'warn')} <code>${p.id}</code> <span class="mut">${p.msg}</span></div>`)}
        <div class="row" style="margin-top:10px"><button class="btn p" data-act="iac.gen" data-w>⚙️ Generate</button><button class="btn" data-act="iac.plan" data-w>🧪 Plan (dry-run)</button><button class="btn" data-act="iac.push" data-w>⬆ Push to Git</button><button class="btn" data-act="iac.dl">⬇ Download</button></div>
        ${IS.planned === 'running' ? h`<p class="mut">Running terraform plan…</p>` : IS.planned ? h`<p><b>Plan:</b> <span class="good">${IS.planned.add} to add</span>, ${IS.planned.change} to change, ${IS.planned.destroy} to destroy · est. <b>${ui.fmt$(IS.planned.cost)}/mo</b></p>` : ''}${IS.pushed ? h`<p class="good">✔ Pushed: ${IS.pushed}</p>` : ''}</div>
      <div class="card"><h2>3 · Output</h2>${IS.out ? h`<div class="tabs"><button class="${IS.tab === 'tf' ? 'on' : ''}" data-act="iac.tab" data-arg="tf">Terraform (HCL)</button><button class="${IS.tab === 'an' ? 'on' : ''}" data-act="iac.tab" data-arg="an">Ansible playbook</button></div>${ui.pre(IS.tab === 'tf' ? IS.out.tf : IS.out.an)}` : h`<div class="empty">Nothing generated yet. Try un-ticking <b>Encrypt</b> or clearing the cost_center tag to see the policy gate block generation.</div>`}</div></div></div>`;
  } });

  /* ================= CLOUD CONFIGURATOR ================= */
  const CF = { scanned: false, method: 'terraform' };
  const sizes = { AWS: ['t3.small', 't3.large', 'm5.large', 'm5.2xlarge'], Azure: ['D2s_v5', 'D4s_v5', 'D8s_v5'], GCP: ['e2-small', 'n2-standard-4'], OpenShift: ['m5.xlarge'], 'IBM Cloud': ['bx2-4x16'] };
  const cfgs = {};
  const cfgOf = x => cfgs[x.id] || (cfgs[x.id] = (() => { const i = +x.id.slice(-2), s = sizes[x.cloud][i % sizes[x.cloud].length]; return { desiredSize: s, actualSize: i % 4 === 0 ? sizes[x.cloud][(i + 1) % sizes[x.cloud].length] : s, desiredEnv: x.env, actualEnv: i % 7 === 0 ? 'dev' : x.env, extraRule: i % 9 === 0 }; })());
  const drift = x => { const c = cfgOf(x), d = []; if (c.desiredSize !== c.actualSize) d.push(['instance_type', c.desiredSize, c.actualSize]); if (c.desiredEnv !== c.actualEnv) d.push(['tags.env', c.desiredEnv, c.actualEnv]); if (c.extraRule) d.push(['sg ingress', '(none)', '0.0.0.0/0:22 (added manually)']); return d; };
  const cands = () => COC.byTenant(D.resources).filter(x => x.state === 'running').slice(0, 14);
  COC.actions['cf.scan'] = () => { CF.scanned = 'running'; COC.refresh(); setTimeout(() => { CF.scanned = true; COC.audit('Drift detection run', cands().filter(x => drift(x).length).length + ' drifted'); COC.refresh(); }, 1100); };
  COC.actions['cf.method'] = v => { CF.method = v; COC.refresh(); };
  COC.actions['cf.reconcile'] = id => { const x = D.resources.find(r => r.id === id), c = cfgOf(x); c.actualSize = c.desiredSize; c.actualEnv = c.desiredEnv; c.extraRule = false; COC.audit('Drift reconciled via ' + CF.method, x.name); COC.toast(x.name + ' reconciled via ' + CF.method, 'ok'); COC.refresh(); };
  COC.actions['cf.accept'] = id => { const x = D.resources.find(r => r.id === id), c = cfgOf(x); c.desiredSize = c.actualSize; c.desiredEnv = c.actualEnv; COC.audit('Drift accepted → desired state updated', x.name); COC.toast('Desired state updated from actual', 'ok'); COC.refresh(); };
  COC.actions['cf.edit'] = id => { const x = D.resources.find(r => r.id === id), c = cfgOf(x); COC.modal({ title: 'Configure ' + x.name, body: h`<label class="f">Size (desired)${ui.select('cf-size', sizes[x.cloud], c.desiredSize, 'noop')}</label><label class="f">Add tag value for env${ui.select('cf-env', D.envs, c.desiredEnv, 'noop')}</label><p class="mut">Will be applied via <b>${CF.method}</b>.</p>`, actions: [{ label: 'Cancel' }, { label: 'Apply', primary: true, fn: () => { c.desiredSize = c.actualSize = COC.v('cf-size'); c.desiredEnv = c.actualEnv = COC.v('cf-env'); x.env = c.desiredEnv; COC.audit('Resource reconfigured via ' + CF.method, x.name); COC.toast('Applied to ' + x.name, 'ok'); COC.refresh(); } }] }); };
  COC.register({ id: 'configurator', name: 'Cloud Configurator', icon: '⚙️', phase: 3, roles: STAFF, render() {
    const rs = cands(), dr = CF.scanned === true ? rs.filter(x => drift(x).length) : [];
    return h`<div class="ph"><div class="grow"><h1>Cloud Configurator</h1><p class="sub">Change existing resources via Terraform or direct API, with drift detection (desired vs. actual).</p></div>
      <div class="row"><label class="mut">Apply via ${ui.select('cf-method', ['terraform', 'direct API'], CF.method, 'cf.method')}</label><button class="btn p" data-act="cf.scan" data-w ${CF.scanned === 'running' ? raw('disabled') : ''}>${CF.scanned === 'running' ? '⏳ Scanning…' : '🔎 Detect drift'}</button></div></div>
      <div class="grid g3">${ui.kpi('Managed resources', rs.length)}${ui.kpi('Drifted', CF.scanned === true ? dr.length : '—', CF.scanned === true ? (dr.length ? 'needs attention' : 'in sync') : 'run a scan', dr.length ? 'bad' : '')}${ui.kpi('Method', CF.method)}</div>
      <div class="card flat">${ui.table([{ h: 'Resource', f: x => x.name }, { h: 'Cloud', f: x => x.cloud }, { h: 'Size (desired → actual)', f: x => { const c = cfgOf(x); return h`${c.desiredSize} → ${CF.scanned === true ? c.actualSize : '?'}`; } }, { h: 'Drift', f: x => { if (CF.scanned !== true) return ui.badge('not scanned', 'mut'); const d = drift(x); return d.length ? h`${d.map(e => h`<div><span class="bad">●</span> <code>${e[0]}</code>: <span class="good">${e[1]}</span> → <span class="bad">${e[2]}</span></div>`)}` : ui.badge('in sync', 'ok'); } }, { h: '', f: x => h`<div class="row">${ui.btn('Configure', 'cf.edit', x.id, { s: 1, w: 1 })}${CF.scanned === true && drift(x).length ? h`${ui.btn('Reconcile', 'cf.reconcile', x.id, { s: 1, p: 1, w: 1 })}${ui.btn('Accept drift', 'cf.accept', x.id, { s: 1, w: 1 })}` : ''}</div>` }], rs)}</div>`;
  } });
})();
